FROM accounts
ORDER BY balance DESC, account_id ASC;

SELECT *
FROM transactions
WHERE transaction_date > DATE '2026-04-01';

SELECT *
FROM accounts
WHERE status = 'Dormant';

SELECT *
FROM accounts
WHERE balance BETWEEN 5000 AND 10000;

SELECT *
FROM accounts
WHERE account_type = 'NRI';

SELECT *
FROM customers
WHERE city = 'Bengaluru';

SELECT *
FROM transactions
WHERE transaction_date > DATE '2025-07-01';

SELECT *
FROM accounts
WHERE status = 'Active';

SELECT c.customer_name, a.account_id, a.account_type, a.balance
FROM customers c
JOIN accounts a ON c.customer_id = a.customer_id;

SELECT *
FROM doctors
WHERE specialization = 'Orthopedics';

SELECT *
FROM patients
WHERE patient_id > 2;

SELECT *
FROM patients
WHERE city = 'Bengaluru';

SELECT *
FROM patients
ORDER BY patient_id DESC, patient_id ASC;

SELECT *
FROM appointments
WHERE appointment_date > DATE '2026-03-01';

SELECT *
FROM appointments
WHERE status = 'Cancelled';

SELECT *
FROM patients
WHERE patient_id BETWEEN 2 AND 3;

SELECT *
FROM doctors
WHERE specialization = 'Pediatrics';

SELECT *
FROM patients
WHERE city = 'Madurai';

SELECT *
FROM appointments
WHERE appointment_date > DATE '2025-06-01';

SELECT *
FROM appointments
WHERE status = 'Completed';

SELECT p.patient_name, a.appointment_date, a.status
FROM patients p
JOIN appointments a ON p.patient_id = a.patient_id;

SELECT status, COUNT(*) AS total_appointments
FROM appointments
GROUP BY status;

SELECT patient_id, SUM(bill_amount) AS total_bill
FROM visits
GROUP BY patient_id;

SELECT patient_id, visit_date,
       LAG(visit_date) OVER (PARTITION BY patient_id ORDER BY visit_date, visit_id) AS previous_visit_date
FROM visits;

SELECT *
FROM policies
WHERE policy_type = 'Vehicle';

SELECT *
FROM policies
WHERE premium_amount > 50000;

SELECT *
FROM customers
WHERE city = 'Coimbatore';

SELECT *
FROM policies
ORDER BY premium_amount DESC, policy_id ASC;

SELECT *
FROM claims
WHERE claim_date > DATE '2026-03-01';

SELECT *
FROM policies
WHERE policy_status = 'Pending';

SELECT *
FROM policies
WHERE premium_amount BETWEEN 10000 AND 20000;

SELECT *
FROM policies
WHERE policy_type = 'Travel';

SELECT *
FROM customers
WHERE city = 'Mumbai';

SELECT *
FROM claims
WHERE claim_date > DATE '2025-06-01';

SELECT *
FROM policies
WHERE policy_status = 'Active';

SELECT c.customer_name, p.policy_id, p.policy_type, p.premium_amount
FROM customers c
JOIN policies p ON c.customer_id = p.customer_id;

SELECT policy_id, SUM(claim_amount) AS total_claim_amount
FROM claims
GROUP BY policy_id;

SELECT claim_status, COUNT(*) AS total_claims
FROM claims
GROUP BY claim_status;

SELECT policy_id, claim_date, claim_amount,
       LAG(claim_amount) OVER (PARTITION BY policy_id ORDER BY claim_date, claim_id) AS previous_claim_amount
FROM claims;

SELECT *
FROM products
WHERE category = 'Grocery';

