SELECT *
FROM customers
WHERE city = 'Hyderabad';

SELECT *
FROM products
ORDER BY stock_qty DESC, product_id ASC;

SELECT *
FROM orders
WHERE order_date > DATE '2026-03-01';

SELECT *
FROM orders
WHERE order_status = 'Pending';

SELECT *
FROM products
WHERE stock_qty BETWEEN 10 AND 40;

SELECT *
FROM products
WHERE category = 'Home';

SELECT *
FROM customers
WHERE city = 'Bengaluru';

SELECT *
FROM orders
WHERE order_date > DATE '2025-06-01';

SELECT *
FROM orders
WHERE order_status = 'Delivered';

SELECT c.customer_name, o.order_id, o.order_date, o.order_status
FROM customers c
JOIN orders o ON c.customer_id = o.customer_id;

SELECT order_status, COUNT(*) AS total_orders
FROM orders
GROUP BY order_status;

SELECT customer_id, order_id, order_date,
       LAG(order_date) OVER (PARTITION BY customer_id ORDER BY order_date, order_id) AS previous_order_date
FROM orders;

Healthcare.schema:
CREATE TABLE patients (
  patient_id INT PRIMARY KEY,
  patient_name VARCHAR(100),
  city VARCHAR(50),
  register_date DATE
);

CREATE TABLE doctors (
  doctor_id INT PRIMARY KEY,
  doctor_name VARCHAR(100),
  specialization VARCHAR(50)
);

CREATE TABLE appointments (
  appointment_id INT PRIMARY KEY,
  patient_id INT,
  doctor_id INT,
  appointment_date DATE,
  status VARCHAR(30)
);

CREATE TABLE visits (
  visit_id INT PRIMARY KEY,
  patient_id INT,
  visit_date DATE,
  bill_amount DECIMAL(12,2)
);

Insurance.schema:
CREATE TABLE customers (
  customer_id INT PRIMARY KEY,
  customer_name VARCHAR(100),
  city VARCHAR(50),
  segment VARCHAR(30)
);

CREATE TABLE policies (
  policy_id INT PRIMARY KEY,
  customer_id INT,
  policy_type VARCHAR(40),
  premium_amount DECIMAL(12,2),
  policy_status VARCHAR(30)
);

CREATE TABLE claims (
  claim_id INT PRIMARY KEY,
  policy_id INT,
  claim_date DATE,
  claim_amount DECIMAL(12,2),
  claim_status VARCHAR(30)
);

Retail.schema:
CREATE TABLE customers (
  customer_id INT PRIMARY KEY,
  customer_name VARCHAR(100),
  city VARCHAR(50),
  segment VARCHAR(30)
);

CREATE TABLE products (
  product_id INT PRIMARY KEY,
  product_name VARCHAR(100),
  category VARCHAR(50),
  stock_qty INT,
  reorder_level INT
);

CREATE TABLE orders (
  order_id INT PRIMARY KEY,
  customer_id INT,
  order_date DATE,
  order_status VARCHAR(30)
);

CREATE TABLE order_items (
  order_id INT,
  product_id INT,
  quantity INT,
  unit_price DECIMAL(12,2)
);
